CREATE TABLE public.workforce_clock_settings (org_id uuid PRIMARY KEY REFERENCES public.organizations(id), timezone text NOT NULL DEFAULT 'America/St_Lucia', overtime_basis text NOT NULL DEFAULT 'weekly', overtime_threshold numeric NOT NULL DEFAULT 40, overtime_multiplier numeric NOT NULL DEFAULT 1.5, attendance_payroll boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.workforce_clock_settings TO authenticated; GRANT ALL ON public.workforce_clock_settings TO service_role;
ALTER TABLE public.workforce_clock_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY workforce_settings_read ON public.workforce_clock_settings FOR SELECT TO authenticated USING (org_id=public.current_org_id());
CREATE TABLE public.workforce_clock_credentials (org_id uuid NOT NULL REFERENCES public.organizations(id), employee_id uuid NOT NULL, employee_code text NOT NULL, pin_hash text NOT NULL, enabled boolean NOT NULL DEFAULT true, failed_attempts integer NOT NULL DEFAULT 0, locked_until timestamptz, PRIMARY KEY(org_id,employee_id), UNIQUE(org_id,employee_code));
GRANT ALL ON public.workforce_clock_credentials TO service_role; ALTER TABLE public.workforce_clock_credentials ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.workforce_schedules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), employee_id uuid NOT NULL, shift_start time NOT NULL, shift_end time NOT NULL, days_of_week integer[] NOT NULL DEFAULT ARRAY[1,2,3,4,5], break_minutes integer NOT NULL DEFAULT 0, site_id uuid REFERENCES public.client_sites(id), enabled boolean NOT NULL DEFAULT true, UNIQUE(org_id,employee_id));
GRANT SELECT ON public.workforce_schedules TO authenticated; GRANT ALL ON public.workforce_schedules TO service_role;
ALTER TABLE public.workforce_schedules ENABLE ROW LEVEL SECURITY;
CREATE POLICY workforce_schedule_read ON public.workforce_schedules FOR SELECT TO authenticated USING (org_id=public.current_org_id() AND (employee_id=auth.uid() OR public.has_workspace_access(auth.uid(),'attendance') AND public.is_admin_or_manager(auth.uid())));
CREATE TABLE public.workforce_shifts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), employee_id uuid NOT NULL, shift_date date NOT NULL, scheduled_start timestamptz, scheduled_end timestamptz, clock_in timestamptz, clock_out timestamptz, break_minutes integer NOT NULL DEFAULT 0, approved_hours numeric, review_status text NOT NULL DEFAULT 'pending', reviewed_by uuid, reviewed_at timestamptz, review_notes text, UNIQUE(org_id,employee_id,shift_date));
GRANT SELECT ON public.workforce_shifts TO authenticated; GRANT ALL ON public.workforce_shifts TO service_role;
ALTER TABLE public.workforce_shifts ENABLE ROW LEVEL SECURITY;
CREATE POLICY workforce_shift_read ON public.workforce_shifts FOR SELECT TO authenticated USING (org_id=public.current_org_id() AND (employee_id=auth.uid() OR public.has_workspace_access(auth.uid(),'attendance') AND public.is_admin_or_manager(auth.uid())));
CREATE TABLE public.workforce_punches (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), employee_id uuid NOT NULL, shift_id uuid NOT NULL REFERENCES public.workforce_shifts(id), direction text NOT NULL, punched_at timestamptz NOT NULL DEFAULT now(), mode text NOT NULL, latitude double precision, longitude double precision);
GRANT SELECT ON public.workforce_punches TO authenticated; GRANT ALL ON public.workforce_punches TO service_role;
ALTER TABLE public.workforce_punches ENABLE ROW LEVEL SECURITY;
CREATE POLICY workforce_punch_read ON public.workforce_punches FOR SELECT TO authenticated USING (org_id=public.current_org_id() AND (employee_id=auth.uid() OR public.has_workspace_access(auth.uid(),'attendance') AND public.is_admin_or_manager(auth.uid())));
CREATE TABLE public.workforce_alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), shift_id uuid NOT NULL REFERENCES public.workforce_shifts(id), employee_id uuid NOT NULL, missing_type text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), resolved_at timestamptz, UNIQUE(shift_id,missing_type));
GRANT SELECT ON public.workforce_alerts TO authenticated; GRANT ALL ON public.workforce_alerts TO service_role;
ALTER TABLE public.workforce_alerts ENABLE ROW LEVEL SECURITY;
CREATE POLICY workforce_alert_read ON public.workforce_alerts FOR SELECT TO authenticated USING (org_id=public.current_org_id() AND public.is_admin_or_manager(auth.uid()) AND public.has_workspace_access(auth.uid(),'attendance'));
ALTER PUBLICATION supabase_realtime ADD TABLE public.workforce_alerts;